<?php
/** Only these definitions can supply SQL identifiers or expressions to admin grids. */
class AdminTables {
 private static function field($header,$kind='text',$extra=array()){return array_merge(array('header'=>$header,'kind'=>$kind),$extra);}
 public static function orderStatus(){$grid=Yii::app()->request->getQuery('Grid',array());$value=is_array($grid)&&isset($grid['orders'])&&is_array($grid['orders'])&&array_key_exists('status',$grid['orders'])?$grid['orders']['status']:Yii::app()->request->getQuery('status','');return is_scalar($value)?(string)$value:'';}
 public static function definition($key,$context=array()){
  $f=function($label,$kind='text',$extra=array()){return self::field($label,$kind,$extra);};$active=array(1=>'فعال',0=>'غیرفعال');$publish=array('published'=>'منتشرشده','draft'=>'پیش‌نویس');
  $edit=function($route,$label='ویرایش ←'){return function($data)use($route,$label){return CHtml::link($label,array($route,'id'=>$data->id),array('class'=>'table-action','data-pjax'=>'1'));};};
  switch($key){
   case 'payments':return array('query'=>'SELECT id,order_id,amount,mode,state,ref_id,created_at FROM payments','fields'=>array('id'=>$f('شناسه','number'),'order_id'=>$f('سفارش','number'),'amount'=>$f('مبلغ (ریال)','number'),'mode'=>$f('حالت','text',array('choices'=>array('sandbox'=>'آزمایشی','live'=>'واقعی'),'value'=>function($r){return $r['mode']==='live'?'واقعی':'آزمایشی';})),'state'=>$f('نتیجه','text',array('choices'=>array('requested'=>'در انتظار پرداخت','paid'=>'تأییدشده','review'=>'نیازمند بررسی'),'value'=>function($r){return array('requested'=>'در انتظار پرداخت','paid'=>'تأییدشده','review'=>'نیازمند بررسی')[$r['state']]??$r['state'];})),'ref_id'=>$f('مرجع'),'created_at'=>$f('تاریخ','date')));
   case 'audit':return array('query'=>'SELECT * FROM audit_log','fields'=>array('actor_id'=>$f('مدیر','number'),'entity'=>$f('بخش'),'entity_id'=>$f('رکورد'),'action'=>$f('عملیات'),'changes'=>$f('تغییرات'),'created_at'=>$f('تاریخ','date')));
   case 'notifications':return array('query'=>'SELECT id,order_id,channel,state,attempts,created_at FROM notifications','fields'=>array('order_id'=>$f('سفارش','number'),'channel'=>$f('روش','text',array('choices'=>array('email'=>'ایمیل','sms'=>'پیامک'),'value'=>function($r){return $r['channel']==='sms'?'پیامک':'ایمیل';})),'state'=>$f('وضعیت','text',array('choices'=>array('pending'=>'در صف','processing'=>'در حال ارسال','sent'=>'ارسال‌شده','failed'=>'ناموفق'),'value'=>function($r){return array('pending'=>'در صف','processing'=>'در حال ارسال','sent'=>'ارسال‌شده','failed'=>'ناموفق')[$r['state']]??$r['state'];})),'attempts'=>$f('تلاش','number'),'created_at'=>$f('تاریخ','date')));

   case 'products':
    $price="(t.price-CASE WHEN t.discount_type='percent' THEN ".(Yii::app()->db->driverName==='mysql'?'FLOOR(t.price*t.discount_value/100)':'CAST(t.price*t.discount_value/100 AS INTEGER)')." WHEN t.discount_type='fixed' THEN t.discount_value ELSE 0 END)";
    return array('model'=>'Product','fields'=>array('id'=>$f('شناسه','number'),'title'=>$f('نام محصول'),'sku'=>$f('SKU'),'price'=>$f('قیمت فروش','money',array('sql'=>$price,'value'=>function($p){return Money::format($p->salePrice());})),'stock'=>$f('موجودی','number'),'status'=>$f('وضعیت','text',array('choices'=>$publish,'value'=>function($p)use($publish){return $publish[$p->status]??$p->status;}))),'action'=>$edit('adminProduct/update'));
   case 'orders':return array('model'=>'Order','fields'=>array('id'=>$f('شناسه','number'),'order_number'=>$f('شماره سفارش','text',array('type'=>'raw','value'=>function($o){return CHtml::link(CHtml::encode($o->order_number),array('adminOrder/view','id'=>$o->id),array('data-pjax'=>'1'));})),'customer_name'=>$f('مشتری'),'customer_phone'=>$f('تلفن'),'total'=>$f('مبلغ','money',array('value'=>function($o){return Money::format($o->total);})),'status'=>$f('وضعیت','text',array('choices'=>Order::model()->statuses(),'type'=>'raw','value'=>function($o){return OrderPresentation::badge($o->status);})),'created_at'=>$f('تاریخ','date')),'action'=>$edit('adminOrder/view','جزئیات ←'));
   case 'order-items':return array('model'=>'OrderItem','with'=>array('product.images'),'condition'=>'t.order_id=:order','params'=>array(':order'=>(int)($context['order']??0)),'order'=>'t.id ASC','fields'=>array('product_title'=>$f('محصول','text',array('type'=>'raw','value'=>function($item){return OrderPresentation::item($item);})),'sku'=>$f('شناسه کالا'),'quantity'=>$f('تعداد','number'),'price'=>$f('قیمت واحد','money',array('value'=>function($item){return Money::format($item->price);})),'line_total'=>$f('مجموع','money',array('value'=>function($item){return Money::format($item->line_total);}))));
   case 'posts':return array('model'=>'Post','fields'=>array('id'=>$f('شناسه','number'),'title'=>$f('عنوان'),'status'=>$f('وضعیت','text',array('choices'=>$publish,'value'=>function($p)use($publish){return $publish[$p->status]??$p->status;})),'created_at'=>$f('تاریخ','date')),'action'=>$edit('adminPost/update'));
   case 'tags':return array('model'=>'Tag','fields'=>array('id'=>$f('شناسه','number'),'name'=>$f('نام'),'slug'=>$f('شناسه URL')),'action'=>$edit('adminTag/update'));
   case 'categories':$categories=Category::options();return array('model'=>'Category','fields'=>array('id'=>$f('شناسه','number'),'name'=>$f('نام دسته'),'parent_id'=>$f('والد','text',array('choices'=>array(0=>'دسته اصلی')+$categories,'sql'=>'COALESCE(t.parent_id,0)','value'=>function($c)use($categories){return $c->parent_id?($categories[$c->parent_id]??'—'):'دسته اصلی';})),'slug'=>$f('شناسه URL'),'sort_order'=>$f('ترتیب','number')),'action'=>$edit('adminCategory/update'));
   case 'collections':return array('model'=>'ProductCollection','fields'=>array('id'=>$f('شناسه','number'),'title'=>$f('عنوان'),'slug'=>$f('شناسه URL'),'is_active'=>$f('وضعیت','text',array('choices'=>$active,'value'=>function($c){return $c->is_active?'فعال':'غیرفعال';}))),'action'=>function($c)use($edit){return $edit('adminCollection/update')($c).' · '.CHtml::link('مشاهده',array('collection/view','slug'=>$c->slug));});
   case 'menus':return array('model'=>'MenuItem','order'=>'t.location ASC,t.sort_order ASC,t.id ASC','fields'=>array('label'=>$f('عنوان'),'url'=>$f('مقصد'),'location'=>$f('محل نمایش','text',array('choices'=>array('header'=>'بالای سایت','footer'=>'پایین سایت'),'value'=>function($m){return $m->location==='header'?'بالای سایت':'پایین سایت';})),'parent_id'=>$f('والد','number'),'sort_order'=>$f('ترتیب','number'),'is_active'=>$f('وضعیت','text',array('choices'=>$active,'value'=>function($m){return $m->is_active?'فعال':'غیرفعال';}))),'action'=>$edit('adminMenu/update'));
   case 'coupons':return array('model'=>'Coupon','fields'=>array('code'=>$f('کد'),'kind'=>$f('نوع تخفیف','text',array('choices'=>array('percent'=>'درصدی','fixed'=>'مبلغ ثابت'),'value'=>function($c){return $c->kind==='percent'?'درصدی':'مبلغ ثابت';})),'amount'=>$f('مقدار تخفیف','mixed-money',array('sql'=>"(CASE WHEN t.kind='fixed' THEN t.amount*".Money::factor().' ELSE t.amount END)','value'=>function($c){return $c->kind==='percent'?number_format($c->amount).'٪':Money::format($c->amount);})),'minimum_total'=>$f('حداقل خرید','money',array('value'=>function($c){return Money::format($c->minimum_total);})),'used_count'=>$f('دفعات مصرف','number'),'usage_limit'=>$f('ظرفیت (۰ نامحدود)','number'),'is_active'=>$f('وضعیت','text',array('choices'=>$active,'value'=>function($c){return $c->is_active?'فعال':'غیرفعال';})),'expires_at'=>$f('انقضا','date')),'action'=>function($c)use($edit){return $edit('adminCoupon/update')($c).' '.CHtml::tag('button',array('type'=>'submit','form'=>'coupon-toggle-'.$c->id,'class'=>'btn btn-outline btn-sm'),$c->is_active?'غیرفعال':'فعال');},'forms'=>function($rows){foreach($rows as $c){echo CHtml::beginForm(array('adminCoupon/toggle','id'=>$c->id),'post',array('id'=>'coupon-toggle-'.$c->id));echo CHtml::endForm();}});
   case 'stock':return array('query'=>'SELECT p.id,p.title,p.stock,COALESCE(SUM(m.quantity),0) ledger,CASE WHEN p.stock=COALESCE(SUM(m.quantity),0) THEN 1 ELSE 0 END matched FROM products p LEFT JOIN inventory_movements m ON m.product_id=p.id GROUP BY p.id,p.title,p.stock','fields'=>array('title'=>$f('محصول'),'stock'=>$f('موجودی قابل فروش','number'),'ledger'=>$f('جمع گردش انبار','number'),'matched'=>$f('تطبیق','text',array('choices'=>array(1=>'مطابق',0=>'نیاز به بررسی'),'type'=>'raw','value'=>function($p){return '<span class="status '.($p['matched']?'status-paid':'status-cancelled').'">'.($p['matched']?'مطابق':'نیاز به بررسی').'</span>';}))));
   case 'finance':return array('query'=>'SELECT f.*,o.order_number FROM financial_entries f JOIN orders o ON o.id=f.order_id','fields'=>array('order_number'=>$f('سفارش','text',array('type'=>'raw','value'=>function($e){return CHtml::link(CHtml::encode($e['order_number']),array('adminOrder/view','id'=>$e['order_id']),array('data-pjax'=>'1'));})),'kind'=>$f('نوع','text',array('choices'=>array('receipt'=>'دریافت','refund'=>'بازپرداخت'),'value'=>function($e){return $e['kind']==='receipt'?'دریافت':'بازپرداخت';})),'amount'=>$f('مبلغ','money',array('value'=>function($e){return Money::format($e['amount']);})),'created_at'=>$f('تاریخ','date')));
   case 'movements':$labels=array('opening'=>'موجودی اولیه','adjustment'=>'اصلاح موجودی','reserve'=>'رزرو','returned'=>'مرجوعی','expired'=>'انقضای رزرو','cancelled'=>'لغو');return array('query'=>'SELECT m.*,p.title,o.order_number FROM inventory_movements m JOIN products p ON p.id=m.product_id LEFT JOIN orders o ON o.id=m.order_id','fields'=>array('title'=>$f('کالا'),'quantity'=>$f('تغییر','number'),'kind'=>$f('علت','text',array('choices'=>$labels,'value'=>function($m)use($labels){return $labels[$m['kind']]??$m['kind'];})),'order_number'=>$f('سفارش'),'created_at'=>$f('تاریخ','date')));
   case 'visit-pages':case 'visit-sources':case 'visit-devices':
    $days=in_array((int)($context['days']??30),array(7,30,90),true)?(int)($context['days']??30):30;$cutoff=date('Y-m-d 00:00:00',strtotime('today')-86400*($days-1));$column=array('visit-pages'=>'path','visit-sources'=>'referrer_host','visit-devices'=>'device')[$key];$label=array('path'=>'مسیر صفحه','referrer_host'=>'منبع ورود','device'=>'دستگاه')[$column];return array('query'=>'SELECT '.$column.',COUNT(*) views FROM page_visits WHERE created_at>=:cutoff AND created_at<:end GROUP BY '.$column,'params'=>array(':cutoff'=>$cutoff,':end'=>date('Y-m-d 00:00:00',strtotime('tomorrow'))),'keyField'=>$column,'order'=>'t.views DESC,t.'.$column.' ASC','fields'=>array($column=>$f($label,'text',array('value'=>function($r)use($column){return $r[$column]?:'ورود مستقیم';})),'views'=>$f('بازدید','number')));
  }throw new CException('Unknown management table');
 }
}
